package com.metabuild.modules.admin.messages;
import static org.assertj.core.api.Assertions.assertThat;import com.metabuild.admin.api.*;import com.metabuild.modules.admin.messages.application.AfterCommitInboxPublisher;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.transaction.support.TransactionSynchronizationManager;
class AfterCommitInboxPublisherTest {@Test void delegatesOnlyAfterCommit(){var calls=new ArrayList<InboxMessageCommand>();InboxPublisher store=commands->{calls.addAll(commands);return new PublishResult(Set.of("key"),Set.of());};var publisher=new AfterCommitInboxPublisher(store);var command=new InboxMessageCommand("key",UUID.fromString("01900000-0000-7000-8000-000000000010"),"system","title","body",null);TransactionSynchronizationManager.initSynchronization();TransactionSynchronizationManager.setActualTransactionActive(true);try{publisher.publish(List.of(command));assertThat(calls).isEmpty();TransactionSynchronizationManager.getSynchronizations().forEach(x->x.afterCommit());assertThat(calls).containsExactly(command);}finally{TransactionSynchronizationManager.setActualTransactionActive(false);TransactionSynchronizationManager.clearSynchronization();}}}
